INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329400, 14250, 'The Guardian', 'en', 'Luigi Mangione to appear in court amid reports of plea deal over healthcare CEO’s killing', 'https://www.theguardian.com/us-news/live/2026/aug/14/luigi-mangione-court-plea-deal-ceo-killing-live', 'Earlier this week prosecutors and Luigi Mangione’s lawyers filed a joint letter requesting the hearing at 11am on Friday in Manhattan federal court If Mangione does wind up pleading guilty, Garnett will ask him some questions about how he’s feeling before the proceedings get to the admission-of-guilt stage. Judges ask these questions at plea proceedings to make sure a person is sound enough to knowingly enter a plea. So, if you see anything pop up on social media that makes these questions sound unique or indicative of something else, ignore that noise and speculation. Continue reading...', 'https://i.guim.co.uk/img/media/b550bdf885704868da2573856582a0cd80c638fe/670_0_4140_3312/master/4140.jpg?width=140&quality=85&auto=format&fit=max&s=a0109df0ae0c4eb704a60262446426e7', '2026-08-14T14:37:26+00:00', '2026-08-14T14:58:19.851014'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
