INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332985, 14250, 'The Times of India', 'en', '''I shot him'': Luigi Mangione pleads guilty to killing United Healthcare CEO', 'https://timesofindia.indiatimes.com/world/us/i-shot-him-luigi-mangione-pleads-guilty-to-killing-united-healthcare-ceo-sentencing-on-dec-18/articleshow/133247371.cms', 'Luigi Mangione has confessed to the fatal shooting of UnitedHealthcare CEO Brian Thompson in Manhattan. He has entered a guilty plea for federal stalking charges in connection to the incident. This plea addresses one of two criminal cases targeting Mangione, while he is still preparing for a state murder trial set for September. During the investigation, authorities found a 3D-printed gun along with a notebook.', 'https://static.toiimg.com/photo/msid-133247463,imgsize-110298.cms', '2026-08-14T16:37:56+00:00', '2026-08-14T17:12:42.078090'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
