INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (323985, 14252, 'South China Morning Post', 'en', '1 dead, 6 wounded in Rotterdam port explosion', 'https://www.scmp.com/news/world/europe/article/3363950/1-dead-several-wounded-rotterdam-port-explosion', 'A blast at a ⁠storage facility for petroleum products at the Netherlands’ Rotterdam port killed one person and wounded six others on Thursday, officials said, as police investigated the cause of the explosion. A spokesperson for major energy commodities trading company Gunvor said an “incident” occurred during maintenance work on a storage tank. A police spokesperson said that there was no immediate ⁠sign of sabotage and that all possible scenarios were under ‌investigation. Rotterdam is...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/fe7e77d5-2305-433c-8030-ad9ff8c911b3_81f635e5.jpg?itok=ew7HU_us&v=1786629456', '2026-08-13T13:57:38+00:00', '2026-08-13T22:55:10.787070'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
