INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322682, 14253, 'The Independent', 'en', 'Karoline Leavitt’s resignation left Trump flat-footed with no plan to replace her as press secretary: official', 'https://www.independent.co.uk/news/world/americas/us-politics/trump-karoline-leavitt-press-secretary-replacement-b3032508.html', 'White House press briefings will be given by top officials — as they had been intermittently during Leavitt’s maternity leave — but names are being bandied about for a down-the-line permanent replacement', 'https://static.independent.co.uk/2026/07/26/16/2026-07-23T160658Z_180517643_RC2SJMAO8WH3_RTRMADP_3_USA-TRUMP.JPG?width=1200&auto=webp&trim=0%2C0%2C0%2C0', '2026-08-13T16:23:24+00:00', '2026-08-13T22:53:04.977954'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
