INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329376, 14256, 'BBC News', 'en', 'Temporary ban on sale of disposable BBQs over wildfire risk', 'https://www.bbc.co.uk/news/articles/c0jlyqdj6geo', 'Single-use grills pose a "significant risk to the public" in current drought and heatwave conditions, the government warns.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/b53b/live/4aaee280-97eb-11f1-a76b-f1c27c51f3da.jpg', '2026-08-14T14:30:46+00:00', '2026-08-14T14:58:14.717868'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329390, 14256, 'The Guardian', 'en', 'Almost 500 arrested on suspicion of starting wildfires in France this summer', 'https://www.theguardian.com/world/2026/aug/14/arrested-suspicion-starting-wildfires-europe-france', 'More than 180 minors among those detained, as firefighters tackle blazes across Europe amid record-breaking heatwave Europe heatwave – latest updates Almost 500 people have been arrested on suspicion of starting wildfires in France since the start of the summer, authorities have said, as firefighters in half a dozen European countries tackle ferocious blazes amid a record-breaking heatwave. With three out of five Europeans facing temperatures of at least 30C on Friday and about 150 million enduring 35C or more, France’s interior ministry said 474 people, including 183 minors, had been detained', 'https://i.guim.co.uk/img/media/4e74294d7fc12a4f6c823be60d68e8ff43d71b97/984_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=40fcf0dd5ba505158e68d69f898bc919', '2026-08-14T12:18:14+00:00', '2026-08-14T14:58:19.678665'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329393, 14256, 'The Guardian', 'en', 'Burnham temporarily bans disposable barbecue sales in ‘tinderbox’ Britain', 'https://www.theguardian.com/environment/2026/aug/14/burnham-temporary-ban-barbecues-tinderbox-britain', 'PM urges people not to risk lives and homes by starting fires as military brought in to help deal with wildfires UK politics live – latest updates Downing Street has issued a temporary GB-wide ban on the sale of disposable barbecue and brought in the military to help deal with wildfires as Andy Burnham urged people not to risk lives in “tinderbox” Britain this weekend. The prime minister spoke from Stourbridge in the West Midlands, where at least 19 people have been taken to hospital during eight fires that have ripped through several homes . Continue reading...', 'https://i.guim.co.uk/img/media/3af8440a11e7c68b64f9fa314cc613c461b05eee/953_817_2259_1807/master/2259.jpg?width=140&quality=85&auto=format&fit=max&s=9d22100d9096dfebb2c979e6bf65f298', '2026-08-14T14:49:47+00:00', '2026-08-14T14:58:19.746446'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
